// The built-in drum kits (plan 25 Task 1, spec 2026-11-19-builtin-content.md
// §1): data only. KITS[0] is the starter kit (samples/starter/, generated by
// scripts/make-starter-kit.mjs; the default drum track is made of it:
// state/defaultKit.ts DEFAULT_KIT derives from it). The others live in
// samples/kits/<id>/<file> and are generated by scripts/make-kits.mjs (the
// sound recipes and their measurements are in that script's comments). All
// CC0.
//
// Every kit has one sound per row role, in KIT_ROLES order. The roles are
// the default drum track's row names, so a kit loads onto any track by role
// (state/kit-actions.ts loadKitOntoTrack) and the factory patterns, whose
// rows are named by role, map onto every kit.
//
// Where the files come from (bundled URLs, fetch) is library/kitFiles.ts.

/** The row roles, top to bottom: the default drum track's row names. */
export const KIT_ROLES = ['Kick', 'Clap', 'Closed hat', 'Open hat', 'Snare', 'Rim', 'Shaker', 'Perc'] as const;
export type KitRole = (typeof KIT_ROLES)[number];

export interface KitSound {
  /** The row it fills (a loaded kit names the row after it). */
  role: KitRole;
  /** What the Browser shows beside the role. */
  name: string;
  /** Its file name inside the kit's folder. */
  file: string;
}

export interface Kit {
  id: string;
  name: string;
  /** One line on its character (the Browser's tooltip). */
  blurb: string;
  /** One sound per role, in KIT_ROLES order. */
  rows: readonly KitSound[];
}

export const STARTER_KIT_ID = 'starter';

/** The generated kits' file per role (scripts/make-kits.mjs ROLE_FILES). */
const ROLE_FILE: Record<KitRole, string> = {
  Kick: 'kick.wav',
  Clap: 'clap.wav',
  'Closed hat': 'closed-hat.wav',
  'Open hat': 'open-hat.wav',
  Snare: 'snare.wav',
  Rim: 'rim.wav',
  Shaker: 'shaker.wav',
  Perc: 'perc.wav',
};

/** A generated kit's rows: role order, ROLE_FILE names, `names` in role order. */
const generated = (names: readonly string[]): KitSound[] => KIT_ROLES.map((role, i) => ({ role, name: names[i], file: ROLE_FILE[role] }));

export const KITS: readonly Kit[] = [
  {
    id: STARTER_KIT_ID,
    name: 'Starter kit',
    blurb: 'The default drum track’s sounds, plus stabs and a sub one-shot',
    // Its files predate the roles: each role names the starter file it uses.
    rows: [
      { role: 'Kick', name: 'kick-punch', file: 'kick-punch.wav' },
      { role: 'Clap', name: 'clap', file: 'clap.wav' },
      { role: 'Closed hat', name: 'hat-closed', file: 'hat-closed.wav' },
      { role: 'Open hat', name: 'hat-open', file: 'hat-open.wav' },
      { role: 'Snare', name: 'snare', file: 'snare.wav' },
      { role: 'Rim', name: 'rim', file: 'rim.wav' },
      { role: 'Shaker', name: 'shaker', file: 'shaker.wav' },
      { role: 'Perc', name: 'perc-tom', file: 'perc-tom.wav' },
    ],
  },
  {
    id: 'drum-machine',
    name: 'Drum Machine',
    blurb: '909-ish: a long-sweep kick, ringing metallic hats, a peaky clap, a body-led snare',
    rows: generated(['Long-sweep kick', 'Four-hand clap', 'Ringing hat', 'Ringing open hat', 'Body snare', 'Rimshot', 'Mid shaker', 'Mid tom']),
  },
  {
    id: 'deep',
    name: 'Deep',
    blurb: 'A round clean boom, soft clap, dusty hats, a conga',
    rows: generated(['Round kick', 'Soft clap', 'Dusty hat', 'Dusty open hat', 'Soft snare', 'Side-stick', 'Soft shaker', 'Conga']),
  },
  {
    id: 'garage',
    name: 'Garage',
    blurb: 'Snappy snare and rim, two-stroke shaker, short hats',
    rows: generated(['Tight kick', 'Snap clap', 'Short hat', 'Short open hat', 'Crack snare', 'Snappy rim', 'Two-step shaker', 'Clave']),
  },
  {
    id: 'dusty',
    name: 'Dusty',
    blurb: 'Lo-fi: bit-crushed, sample-rate reduced, hiss and crackle',
    rows: generated(['Crushed kick', 'Crushed clap', 'Crushed hat', 'Crushed open hat', 'Crushed snare', 'Crushed rim', 'Crushed shaker', 'Crushed bongo']),
  },
];

export function kitById(id: string): Kit | undefined {
  return KITS.find((k) => k.id === id);
}

/** Does a row named `name` play `role`? Case and surrounding spaces don't matter. */
export function rowHasRole(name: string, role: KitRole): boolean {
  return name.trim().toLowerCase() === role.toLowerCase();
}
